style.css:
@-moz-document domain("roblox.com") {
body {
    background-color: #ffe6f0 !important;
    font-family: "Comic Sans MS", cursive !important;
  }

  .navbar, .footer {
    background-color: #ff99cc !important;
  }

  a, button {
    color: #800040 !important;
  }
}

@-moz-document domain("roblox.com") {
body {
    background-image: url("https://i.imgur.com/TV8qHJ2.png"); /* sem vlož odkaz na obrázek */
    background-repeat: no-repeat;
    background-position: center top;
    background-size: contain; /* nebo cover, podle potřeby */
    background-color: #ffe6f0 !important; /* růžové pozadí pokud obrázek není */
    font-family: "Comic Sans MS", cursive !important;
    color: #800040 !important;
  }
}
